function updateHUD(){ $('#goldCount').textContent=shards;$('#killCount').textContent=kills;$('#levelText').textContent='LV '+String(heroLv).padStart(2,'0');$('#hpFill').style.width=(player.hp/player.maxHp*100)+'%';$('#xpFill').style.width=(xp/xpNeed*100)+'%';$('#hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp} VITALITY`;$('#xpText').textContent=`${xp} / ${xpNeed} XP`;$('#stageText').innerHTML=`${stageName.toUpperCase()} <em>· ${String(stage).padStart(2,'0')}</em>`;$('#timerText').textContent=`${String(Math.floor(stageClock/60)).padStart(2,'0')}:${String(Math.floor(stageClock%60)).padStart(2,'0')}`;$('#threatText').textContent=boss?'DREAD KNIGHT':enemies.length>16?'SWARMING':enemies.length>6?'HUNTED':'QUIET';$('#threatText').style.color=enemies.length>16?'#e57c64':enemies.length>6?'#d8b86e':'#8ec3a9';$('#weaponName').textContent=weaponData[player.weapon][0];$('#weaponSub').textContent=weaponData[player.weapon][1];$('#weaponIcon').textContent=weaponData[player.weapon][2];$('#sign1').classList.toggle('active',chosen.has('sign'));$('#sign2').classList.toggle('active',chosen.has('aard'));$('#sign3').classList.toggle('active',chosen.has('vamp'))}
function start(){document.querySelectorAll('.overlay').forEach(x=>x.classList.add('hidden'));playing=true;paused=false;dead=false;elapsed=0;stageClock=0;stage=1;kills=0;stageKills=0;shards=0;runXp=0;xp=0;heroLv=1;xpNeed=40;enemies=[];orbs=[];particles=[];slashes=[];boss=null;chosen=new Set();const nodes=meta.nodes||[];player.maxHp=100+(nodes.includes('vitality')?20:0);player.hp=player.maxHp;player.damage=18*(nodes.includes('damage')?1.12:1);player.speed=178*(nodes.includes('speed')?1.08:1);player.attackRange=175;player.attackRate=.65;player.crit=.06+(nodes.includes('crit')?.03:0);player.armor=0;player.regen=nodes.includes('heal')?1:0;player.dodge=0;player.signPower=1;player.x=world.w/2;player.y=world.h/2;stageName=pick(maps)[0];makeMap();updateHUD();$('#startScreen').classList.add('hidden');last=performance.now();requestAnimationFrame(loop)}
function spawnEnemy(isBoss=false){let a=rand(0,Math.PI*2),dist=rand(Math.min(W,H)*.65,Math.min(W,H)*.95),x=clamp(player.x+Math.cos(a)*dist,24,world.w-24),y=clamp(player.y+Math.sin(a)*dist,24,world.h-24);if(isBoss){boss={x,y,hp:520+stage*90,max:520+stage*90,r:25,speed:22,dmg:28,attack:0};enemies.push({...boss,name:'Dread Knight',kind:'knight',color:'#bc6556',hp:boss.hp,maxHp:boss.max,r:25,speed:22,dmg:28,boss:true,attack:0});$('#bossBar').classList.remove('hidden');toast('THE DREAD KNIGHT HAS FOUND YOU')}else{let t=pick(types.slice(0,Math.min(types.length,8+stage*2)));let scale=1+(stage-1)*.23;enemies.push({x,y,hp:t.hp*scale,maxHp:t.hp*scale,speed:t.speed*(1+stage*.025),dmg:t.dmg*(1+stage*.08),r:t.id===14||t.id===18?19:11+Math.random()*4,name:t.name,kind:t.kind,color:t.color,id:t.id,attack:rand(.1,1.2),phase:rand(0,6)})}}
function gainXp(v){xp+=v;runXp+=v;while(xp>=xpNeed){xp-=xpNeed;heroLv++;xpNeed=Math.round(xpNeed*1.35);player.maxHp+=5;player.hp=Math.min(player.maxHp,player.hp+22);player.damage*=1.05;toast(`EXPERIENCE GAINED · LEVEL ${heroLv}`);burst(player.x,player.y,'#f1d77d',18)}updateHUD()}
function toast(t){let n=$('#toast');n.textContent=t;n.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove('show'),1800)}
function burst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-100,100),vy:rand(-100,100),life:rand(.2,.55),max:.55,color,size:rand(2,5)})}
function hurt(n){if(player.invuln>0)return;player.hp-=Math.max(1,n-player.armor);player.invuln=.55;$('#flash').classList.add('hit');setTimeout(()=>$('#flash').classList.remove('hit'),120);burst(player.x,player.y,'#dd7265',8);if(player.hp<=0)endRun();updateHUD()}
function attack(){let target=null,best=player.attackRange;for(let e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(d<best){best=d;target=e}}if(!target)return;let crit=Math.random()<player.crit,damage=player.damage*(crit?2:1);target.hp-=damage;slashes.push({x1:player.x,y1:player.y,x2:target.x,y2:target.y,life:.16,color:crit?'#fff0a0':'#bde0cf'});burst(target.x,target.y,crit?'#f5d477':'#d7e5cd',crit?7:4);if(crit&&player.critDmg)target.hp-=damage*player.critDmg;if(target.hp<=0){enemies.splice(enemies.indexOf(target),1);kills++;stageKills++;shards+=Math.ceil(Math.random()*2);let value=target.boss?150:Math.ceil(8+stage*2);orbs.push({x:target.x,y:target.y,r:target.boss?12:5,value,color:target.boss?'#f4cf67':'#a9d8bd'});if(player.vamp)player.hp=Math.min(player.maxHp,player.hp+1);if(target.boss){boss=null;$('#bossBar').classList.add('hidden');toast('THE DREAD KNIGHT IS FELLED')}updateHUD()}else if(target.boss){boss=target;$('#bossHpFill').style.width=(target.hp/target.maxHp*100)+'%';$('#bossHpText').textContent=Math.ceil(target.hp/target.maxHp*100)+'%'}}
function castSign(kind){if(!playing||paused)return;let found=chosen.has(kind);if(kind==='sign'&&!found){toast('NO SIGN EQUIPPED');return}if(kind==='aard'&&!found){toast('NO SIGN EQUIPPED');return}if(kind==='sign'){for(let e of [...enemies])if(Math.hypot(e.x-player.x,e.y-player.y)<130){e.hp-=54*player.signPower;burst(e.x,e.y,'#ff994c',8);if(e.hp<=0){enemies.splice(enemies.indexOf(e),1);kills++;gainXp(8)}}burst(player.x,player.y,'#ff9b4e',30);signClock=8}else if(kind==='aard'){for(let e of enemies){let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy);if(d<175){e.hp-=35*player.signPower;e.x+=dx/(d||1)*40;e.y+=dy/(d||1)*40}}burst(player.x,player.y,'#92d8e6',28);signClock=7}else {player.hp=Math.min(player.maxHp,player.hp+30);burst(player.x,player.y,'#8ee1b3',20);signClock=10}updateHUD()}
function update(dt){elapsed+=dt;stageClock+=dt;spawnClock+=dt;attackClock+=dt;signClock=Math.max(0,signClock-dt);player.invuln=Math.max(0,player.invuln-dt);player.dodgeCd=Math.max(0,player.dodgeCd-dt);player.hp=Math.min(player.maxHp,player.hp+(player.regen||0)*dt);let ix=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+touch.x,iy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+touch.y;let len=Math.hypot(ix,iy);if(len>1){ix/=len;iy/=len}let boost=player.dodge>0?1.45:1;player.x=clamp(player.x+ix*player.speed*boost*dt,18,world.w-18);player.y=clamp(player.y+iy*player.speed*boost*dt,18,world.h-18);if(player.dodge>0)player.dodge=Math.max(0,player.dodge-dt);if(player.regen)player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);
if(keys.Space&&player.dodgeCd<=0){player.dodge=.22;player.invuln=.4;player.dodgeCd=1.6*(player.dodge?0.68:1);player.x=clamp(player.x+(ix||Math.cos(elapsed*9))*65,18,world.w-18);player.y=clamp(player.y+(iy||Math.sin(elapsed*9))*65,18,world.h-18);keys.Space=false;burst(player.x,player.y,'#e1d18f',10)}
if(spawnClock>Math.max(.5,1.7-stage*.07)&&enemies.length<40){spawnClock=0;spawnEnemy()}
if(stageClock>48&&!boss){spawnEnemy(true)}
if(stageClock>62&&!boss){stage++;stageClock=0;stageKills=0;stageName=pick(maps)[0];makeMap();for(let i=0;i<2+stage;i++)spawnEnemy();showCards()}
if(attackClock>player.attackRate){attackClock=0;attack()}
for(let e of enemies){let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>e.r+player.r+4){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}e.attack-=dt;if(d<e.r+player.r+4&&e.attack<=0){e.attack=e.boss?1.1:1.45;hurt(e.dmg)}if(e.kind==='archer'&&d<230&&d>150){e.x-=dx/d*e.speed*dt*.4;e.y-=dy/d*e.speed*dt*.4}}
for(let o of [...orbs]){let dx=player.x-o.x,dy=player.y-o.y,d=Math.hypot(dx,dy);if(d<100){o.x+=dx/(d||1)*340*dt;o.y+=dy/(d||1)*340*dt}if(d<player.r+o.r+5){orbs.splice(orbs.indexOf(o),1);gainXp(Math.round(o.value*(chosen.has('xp')?1.35:1)));shards+=o.value>100?20:0;updateHUD()}}
particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;return p.life>0});slashes=slashes.filter(s=>(s.life-=dt)>0);updateHUD()}
function showCards(){playing=false;let available=cards.filter(c=>!chosen.has(c[4])||['damage','health','speed','crit','range','rate'].includes(c[4]));let hand=[];while(hand.length<3){let c=pick(available);if(!hand.includes(c))hand.push(c)}$('#cardLevel').textContent=heroLv;$('#cards').innerHTML='';hand.forEach(c=>{let el=document.createElement('button');el.className='relic-card';el.innerHTML=`<div class="card-icon">${c[2]}</div><div class="tag">${c[1]}</div><h3>${c[0]}</h3><p>${c[3]}</p><span class="take">CHOOSE →</span>`;el.onclick=()=>chooseCard(c);$('#cards').append(el)});$('#cardScreen').classList.remove('hidden')}
function chooseCard(c){chosen.add(c[4]);switch(c[4]){case'damage':player.damage*=c[5];break;case'health':player.maxHp+=c[5];player.hp=player.maxHp;break;case'speed':player.speed*=c[5];break;case'crit':player.crit+=c[5];break;case'range':player.attackRange*=c[5];break;case'regen':player.regen=(player.regen||0)+c[5];break;case'rate':player.attackRate*=c[5];break;case'xp':chosen.add('xp');break;case'armor':player.armor+=c[5];break;case'vamp':player.vamp=true;break;case'critDmg':player.critDmg=(player.critDmg||0)+c[5];break;case'dodge':player.dodge=.68;break;case'sign':case'aard':chosen.add(c[4]);break;case'signPower':player.signPower+=c[5];break}$('#cardScreen').classList.add('hidden');player.weapon=(player.weapon+1+Math.floor(Math.random()*4))%weaponData.length;stageClock=0;stageName=pick(maps)[0];makeMap();for(let i=0;i<2+stage;i++)spawnEnemy();playing=true;last=performance.now();toast(`${c[0].toUpperCase()} ACQUIRED`);updateHUD();requestAnimationFrame(loop)}
function endRun(){playing=false;dead=true;let earned=runXp+stage*22+kills*2;meta.xp=(meta.xp||0)+earned;localStorage.setItem('witchlight-meta',JSON.stringify(meta));$('#finalKills').textContent=kills;$('#finalStages').textContent=stage-1;$('#finalXp').textContent=runXp;$('#earnedXp').textContent=earned;$('#deathScreen').classList.remove('hidden');$('#bossBar').classList.add('hidden');}
function worldToScreen(x,y,camx,camy){return [x-camx+W/2,y-camy+H/2]}
function drawGround(camx,camy){let [a,b]=maps.find(m=>m[0]===stageName)||maps[0];ctx.fillStyle=a;ctx.fillRect(0,0,W,H);let tile=54,ox=((-camx+W/2)%tile+tile)%tile,oy=((-camy+H/2)%tile+tile)%tile;for(let x=ox-tile;x<W+tile;x+=tile)for(let y=oy-tile;y<H+tile;y+=tile){let gx=Math.floor((x+camx-W/2)/tile),gy=Math.floor((y+camy-H/2)/tile);ctx.fillStyle=((gx*17+gy*13+world.seed|0)%5===0)?b:((gx+gy)%2?'#ffffff05':'#00000004');ctx.fillRect(x,y,tile-1,tile-1);if((gx*53+gy*7+Math.floor(world.seed))%17===0){ctx.fillStyle='#b9b08a16';ctx.fillRect(x+8,y+13,2,2);ctx.fillRect(x+31,y+38,2,2)}}}
function drawProp(x,y,type,s,rot){let [sx,sy]=worldToScreen(x,y,viewX,viewY);if(sx<-40||sx>W+40||sy<-45||sy>H+30)return;ctx.save();ctx.translate(sx,sy);ctx.rotate(rot);if(type==='reed'){ctx.strokeStyle='#778d6c';ctx.lineWidth=2;for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(i*4,4);ctx.lineTo(i*6-4,-rand(8,22));ctx.stroke()}}else if(type==='stone'){ctx.fillStyle='#5e6256';ctx.fillRect(-8*s,-4*s,16*s,8*s);ctx.fillStyle='#858476';ctx.fillRect(-5*s,-6*s,9*s,3*s)}else{ctx.fillStyle='#1b2824';ctx.beginPath();ctx.moveTo(0,-25*s);ctx.lineTo(13*s,0);ctx.lineTo(-14*s,0);ctx.fill();ctx.fillStyle='#485447';ctx.fillRect(-2*s,-5*s,4*s,9*s)}ctx.restore()}
function drawActor(o,isPlayer=false){let [x,y]=worldToScreen(o.x,o.y,viewX,viewY);if(x<-60||x>W+60||y<-70||y>H+60)return;let r=o.r||13;ctx.fillStyle='#090d0d77';ctx.beginPath();ctx.ellipse(x,y+5,r*1.15,r*.48,0,0,Math.PI*2);ctx.fill();if(!isPlayer){ctx.fillStyle=o.color;ctx.fillRect(Math.round(x-r*.68),Math.round(y-r*.8),Math.round(r*1.36),Math.round(r*1.55));ctx.fillStyle='#d5c59b';ctx.fillRect(x-r*.43,y-r*.95,Math.max(3,r*.26),3);ctx.fillRect(x+r*.16,y-r*.95,Math.max(3,r*.26),3);if(o.kind==='wolf'||o.kind==='hound'){ctx.fillStyle=o.color;ctx.fillRect(x-r,y-r*.35,r*2,r*.65);ctx.fillRect(x+r*.3,y-r*.65,r*.7,r*.35)}if(o.kind==='spider'){ctx.strokeStyle=o.color;ctx.lineWidth=2;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+i*15,y-12);ctx.moveTo(x,y);ctx.lineTo(x+i*15,y+12);ctx.stroke()}}if(o.boss){ctx.fillStyle='#d0b779';ctx.fillRect(x-9,y-r-10,18,5);ctx.fillRect(x-5,y-r-14,3,7);ctx.fillRect(x+2,y-r-14,3,7)}}else{if(player.invuln>0&&Math.floor(elapsed*20)%2===0)ctx.globalAlpha=.5;ctx.fillStyle='#d7d1b3';ctx.fillRect(x-8,y-11,16,21);ctx.fillStyle='#283332';ctx.fillRect(x-7,y-14,14,7);ctx.fillStyle='#ece4c9';ctx.fillRect(x-5,y-7,10,5);ctx.fillStyle='#aaaca0';ctx.fillRect(x-10,y+6,7,8);ctx.fillRect(x+3,y+6,7,8);ctx.fillStyle='#bd9d59';ctx.fillRect(x+6,y-8,3,15);ctx.fillStyle='#d8d1b5';ctx.fillRect(x+7,y-13,2,9);ctx.globalAlpha=1;if(chosen.has('sign')||chosen.has('aard')){ctx.strokeStyle='#e2cb75aa';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,20+Math.sin(elapsed*3)*2,0,Math.PI*2);ctx.stroke()}}}
let viewX=0,viewY=0;function render(){viewX=clamp(player.x, W/2,world.w-W/2);viewY=clamp(player.y,H/2,world.h-H/2);drawGround(viewX,viewY);for(let d of world.decor)drawProp(d.x,d.y,d.type,d.s,d.rot);orbs.forEach(o=>{let [x,y]=worldToScreen(o.x,o.y,viewX,viewY);ctx.shadowBlur=14;ctx.shadowColor=o.color;ctx.fillStyle=o.color;ctx.fillRect(x-o.r,y-o.r,o.r*2,o.r*2);ctx.shadowBlur=0});enemies.sort((a,b)=>a.y-b.y).forEach(e=>drawActor(e));drawActor(player,true);for(let p of particles){let [x,y]=worldToScreen(p.x,p.y,viewX,viewY);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(x,y,p.size,p.size)}ctx.globalAlpha=1;for(let s of slashes){let [x1,y1]=worldToScreen(s.x1,s.y1,viewX,viewY),[x2,y2]=worldToScreen(s.x2,s.y2,viewX,viewY);ctx.globalAlpha=s.life/.16;ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}ctx.globalAlpha=1;let grad=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.18,W/2,H/2,Math.max(W,H)*.72);grad.addColorStop(0,'#00000000');grad.addColorStop(1,'#080e10b8');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)}
function loop(now){if(!playing)return;let dt=Math.min(.04,(now-last)/1000||.016);last=now;update(dt);render();if(playing)requestAnimationFrame(loop)}
function openCodex(){playing=false;buildCodex();$('#codexScreen').classList.remove('hidden')}
function buildCodex(){ $('#legacyXp').textContent=meta.xp||0;$('#metaXpText').textContent=`${meta.xp||0} EARNED XP`;let grid=$('#skillGrid');grid.innerHTML='';legacy.forEach(n=>{let unlocked=(meta.nodes||[]).includes(n[4]),el=document.createElement('div');el.className='skill-node '+(unlocked?'unlocked':'');el.innerHTML=`<div class="node-head"><span>${n[1]}</span><small>${unlocked?'OWNED':`✦ ${n[3]}`}</small></div><h3>${n[0]}</h3><p>${n[2]}</p><button ${unlocked||meta.xp<n[3]?'disabled':''}>${unlocked?'UNLOCKED':meta.xp<n[3]?'NEED MORE XP':'UNLOCK'}</button>`;el.querySelector('button').onclick=()=>{meta.xp-=n[3];meta.nodes=meta.nodes||[];meta.nodes.push(n[4]);localStorage.setItem('witchlight-meta',JSON.stringify(meta));buildCodex()};grid.append(el)})}
$('#startBtn').onclick=start;$('#againBtn').onclick=start;$('#treeBtn').onclick=()=>openCodex();$('#deathCodex').onclick=()=>{ $('#deathScreen').classList.add('hidden');openCodex()};$('#closeCodex').onclick=()=>{$('#codexScreen').classList.add('hidden');if(!dead)$('#startScreen').classList.remove('hidden')};$('#resetMeta').onclick=()=>{meta={xp:0,nodes:[]};localStorage.setItem('witchlight-meta',JSON.stringify(meta));buildCodex()};$('#soundBtn').onclick=e=>{muted=!muted;e.currentTarget.textContent=muted?'♫̸':'♫';toast(muted?'SOUND OFF':'SOUND ON')};$('#dodgeBtn').addEventListener('pointerdown',e=>{e.preventDefault();keys.Space=true});$('#signBtn').addEventListener('pointerdown',e=>{e.preventDefault();castSign(chosen.has('sign')?'sign':chosen.has('aard')?'aard':'vamp')});
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key===' '?'Space':e.key]=true;if(e.key==='1')castSign('sign');if(e.key==='2')castSign('aard');if(e.key==='3')castSign('vamp');if(e.key==='Escape'&&playing){playing=false;paused=true;toast('HUNT PAUSED · PRESS ESC TO RETURN');setTimeout(()=>{if(paused){paused=false;playing=true;last=performance.now();requestAnimationFrame(loop)}},1200)}});addEventListener('keyup',e=>{keys[e.key===' '?'Space':e.key]=false});
const stick=$('#stick'),knob=stick.querySelector('.stick-knob');stick.addEventListener('pointerdown',e=>{e.preventDefault();joystick=e.pointerId;stick.setPointerCapture(joystick);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===joystick)moveStick(e)});stick.addEventListener('pointerup',e=>{if(e.pointerId===joystick){touch={x:0,y:0};knob.style.transform='translate(0,0)';joystick=null}});stick.addEventListener('pointercancel',()=>{touch={x:0,y:0};knob.style.transform='translate(0,0)';joystick=null});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=33;if(d>max){dx*=max/d;dy*=max/d}touch={x:dx/max,y:dy/max};knob.style.transform=`translate(${dx}px,${dy}px)`}
makeMap();stageName=maps[0][0];updateHUD();render();
})();

